import React from 'react';
import * as Yup from 'yup';
import { useForm } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import FormProvider from '../../components/hook-form/FormProvider';
import { Alert, Button, IconButton, InputAdornment, Stack } from '@mui/material';
import { RHFTextField } from '../../components/hook-form';
import { Eye, EyeSlash } from 'phosphor-react';
import { useDispatch } from 'react-redux';
import { RegisterUser } from '../../redux/slices/auth';


const RegisterForm = () => {

    const [showPassword, setShowPassword] = React.useState(false);
    const dispatch = useDispatch();

    const RegisterSchema = Yup.object().shape({
        firstName: Yup.string().required("First name is required"),
        lastName: Yup.string().required("Last name is required"),
        email: Yup.string().required("Email is required").email("Email must be a valid email address"),
        password: Yup.string().required("Password is required").min(8, 'Password must be atleast 8 characters'),
        confirmPassword: Yup.string().required("Password is required").oneOf([Yup.ref('password'), null], 'Passwords must match'),
    });

    const defaultValues = {
        firstName: "",
        lastName: "",
        email: "example@email.com",
        password: "A$tR0nGpassw0rD",
        confirmPassword: "A$tR0nGpassw0rD"
    }

    const methods = useForm({
        resolver: yupResolver(RegisterSchema),
        defaultValues,

    });

    const { reset, setError, handleSubmit, formState: { errors, isSubmitting, isSubmitSuccessful } } = methods;

    const onSubmit = async (data) => {
        try {
            dispatch(RegisterUser(data));   
        } catch (error) {
            console.log(error);
            reset();
            setError("after Submit", {
                ...error,
                message: error.message,
            })
        }
    }


    return (
        <>
            <FormProvider methods={methods} onSubmit={handleSubmit(onSubmit)}>
                <Stack spacing={3}>
                    {!!errors.afterSubmit && <Alert severity='error'>{errors.afterSubmit.message}</Alert>}
                    <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
                        <RHFTextField name='firstName' label='First Name' />
                        <RHFTextField name='lastName' label='Last Name' />
                    </Stack>
                    <RHFTextField name='email' label='Email address' />
                    <RHFTextField name='password' label="Password" type={showPassword ? "text" : "password"} InputProps={{
                        endAdornment: (
                            <InputAdornment>
                                <IconButton onClick={() => { setShowPassword(!showPassword) }}>
                                    {showPassword ? <Eye /> : <EyeSlash />}
                                </IconButton>
                            </InputAdornment>
                        )
                    }} />
                    <RHFTextField name='confirmPassword' label="Confirm Password" type={showPassword ? "text" : "password"} InputProps={{
                        endAdornment: (
                            <InputAdornment>
                                <IconButton onClick={() => { setShowPassword(!showPassword) }}>
                                    {showPassword ? <Eye /> : <EyeSlash />}
                                </IconButton>
                            </InputAdornment>
                        )
                    }} />
                
                <Button
                    fullWidth
                    color='inherit'
                    size='large'
                    type='submit'
                    variant='contained'
                    sx={{
                        bgcolor: 'text.primary',
                        color: (theme) => theme.palette.mode === "light" ? "common.white" : "grey.800",
                        '&:hover': {
                            bgcolor: 'text.primary',
                            color: (theme) => theme.palette.mode === 'light' ? 'common.white' : 'grey:800'
                        }
                    }}>
                    Create Account
                </Button>
                </Stack>
            </FormProvider>
        </>
    )
}

export default RegisterForm;